import networkx as nx
from pysat.solvers import RC2
from pysat.formula import WCNF
from itertools import combinations

n = 14
girth = 7

wcnf = WCNF()

# Variables for edges: e_{i,j} for i < j
def edge_var(i, j):
    if i > j:
        i, j = j, i
    return i * n + j + 1

# No cycles of length 3, 4, 5, 6
for length in range(3, girth):
    import itertools
    for cycle in itertools.combinations(range(n), length):
        for p in itertools.permutations(cycle):
            # To avoid duplicates, only consider permutations where p[0] is min, and p[1] < p[-1]
            if p[0] == min(p) and p[1] < p[-1]:
                clause = []
                for k in range(length):
                    clause.append(-edge_var(p[k], p[(k+1)%length]))
                wcnf.append(clause)

# Maximize edges
for i in range(n):
    for j in range(i+1, n):
        wcnf.append([edge_var(i, j)], weight=1)

with RC2(wcnf) as rc2:
    model = rc2.compute()
    if model:
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                if model[edge_var(i, j) - 1] > 0:
                    edges.append((i, j))
        print(f"Max edges: {len(edges)}")
        print(edges)
    else:
        print("UNSAT")

from pysat.solvers import Solver
from pysat.card import CardEnc
import itertools

n = 14
girth = 7
min_edges = 19
colors = 3

solver = Solver(name='glucose4')

# Variables
# Edges: 1 to n*(n-1)//2
def E(i, j):
    if i > j:
        i, j = j, i
    # i from 0 to n-2, j from i+1 to n-1
    # index = i*n - i*(i+1)//2 + j - i - 1 + 1
    return i * n - i * (i + 1) // 2 + j - i

num_edges = n * (n - 1) // 2

# Colors: num_edges + 1 to num_edges + n*colors
def C(i, c):
    return num_edges + i * colors + c + 1

# 1. Girth >= 7
for length in range(3, girth):
    for cycle in itertools.combinations(range(n), length):
        for p in itertools.permutations(cycle):
            if p[0] == min(p) and p[1] < p[-1]:
                clause = []
                for k in range(length):
                    clause.append(-E(p[k], p[(k+1)%length]))
                solver.add_clause(clause)

# 2. 3-colorable
for i in range(n):
    # At least one color
    solver.add_clause([C(i, c) for c in range(colors)])
    # At most one color
    for c1, c2 in itertools.combinations(range(colors), 2):
        solver.add_clause([-C(i, c1), -C(i, c2)])

for i in range(n):
    for j in range(i+1, n):
        for c in range(colors):
            solver.add_clause([-E(i, j), -C(i, c), -C(j, c)])

# 3. At least 19 edges
edge_vars = [E(i, j) for i in range(n) for j in range(i+1, n)]
cnf = CardEnc.atleast(lits=edge_vars, bound=min_edges, top_id=num_edges + n*colors)
for clause in cnf.clauses:
    solver.add_clause(clause)

print("Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            if model[E(i, j) - 1] > 0:
                edges.append((i, j))
    print(edges)
    print(f"Number of edges: {len(edges)}")
else:
    print("UNSAT")

