from ortools.sat.python import cp_model

model = cp_model.CpModel()
n = 14
girth = 7

edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[i, j] = model.NewBoolVar(f'e_{i}_{j}')

def E(i, j):
    return edges[min(i, j), max(i, j)]

import itertools
for length in range(3, girth):
    for cycle in itertools.combinations(range(n), length):
        for p in itertools.permutations(cycle):
            if p[0] == min(p) and p[1] < p[-1]:
                model.AddBoolOr([E(p[k], p[(k+1)%length]).Not() for k in range(length)])

model.Maximize(sum(edges.values()))

solver = cp_model.CpSolver()
solver.parameters.max_time_in_seconds = 30
status = solver.Solve(model)

if status in [cp_model.OPTIMAL, cp_model.FEASIBLE]:
    print(f"Max edges: {int(solver.ObjectiveValue())}")
else:
    print("No solution found")

import random
import networkx as nx

def get_girth(G):
    girth = float('inf')
    for n in G.nodes():
        # BFS to find shortest cycle
        dist = {n: 0}
        parent = {n: None}
        q = [n]
        while q:
            u = q.pop(0)
            for v in G.neighbors(u):
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    girth = min(girth, dist[u] + dist[v] + 1)
    return girth

def search():
    for _ in range(10000):
        G = nx.Graph()
        G.add_nodes_from(range(14))
        edges = list(nx.non_edges(G))
        random.shuffle(edges)
        for e in edges:
            G.add_edge(*e)
            if get_girth(G) < 7:
                G.remove_edge(*e)
            if G.number_of_edges() >= 19:
                return G
    return None

G = search()
if G:
    print("Found:", G.edges())
    print("Edges:", G.number_of_edges())
else:
    print("Not found")

