    for cycle in itertools.combinations(range(n), length):
        for p in itertools.permutations(cycle):
            if p[0] == min(p) and p[1] < p[-1]:
                s.add(Or([Not(E[p[k]][p[(k+1)%length]]) for k in range(length)]))

# At least 19 edges
edge_vars = [If(E[i][j], 1, 0) for i in range(n) for j in range(i+1, n)]
s.add(Sum(edge_vars) >= min_edges)

